<template>
  <main class="agreement-workspace">
    <header class="archive-heading"><div><p class="eyebrow">Organization files</p><h1>Business agreements</h1><p>Prepare an agreement, collect authorized signatures, and retain its exact signed copy with your organization.</p></div><router-link :to="route.params?.organizationSlug ? `/${route.params.organizationSlug}/admin/agencies` : '/admin/agencies'">Organization settings →</router-link></header>
    <div class="agreement-callout"><strong>Legal entities sign; product names identify services.</strong> SchoolCareBridge is a program of MH4Kidz. AuricWell and Plotline are product names. Confirm the actual contracting parties, service scope, and any applicable HIPAA roles before approval. This workspace does not decide which agreements your organization requires.</div>
    <p v-if="error" class="agreement-error" role="alert">{{error}}</p><p v-if="message" class="agreement-success" role="status">{{message}}</p>
    <label class="organization-picker">Organization<select v-model="agencyId" :disabled="busy" @change="loadArchive"><option value="">Choose an organization</option><option v-for="org in organizations" :key="org.id" :value="String(org.id)">{{org.name}}</option></select></label>
    <p v-if="!organizations.length && !busy">No organizations are available for your active administrator account.</p>
    <div v-if="agencyId && actor" class="archive-layout">
      <aside class="archive-list"><h2>{{organization.name}}</h2><p class="muted">Agreements and uploaded originals stay in this organization's archive. They are never patient records or hiring tasks.</p><label>Agreement type<select v-model="newType"><option value="baa">Business Associate Agreement</option><option value="management_agreement">Management services agreement</option></select></label><button :disabled="busy" @click="createDraft">+ Prepare draft</button>
        <button v-for="record in documents" :key="record.id" class="archive-item" :class="{selected:selected?.id===record.id}" :disabled="busy" @click="choose(record)"><strong>{{record.data.title}}</strong><span>{{statusLabel(record.data.status)}} · version {{record.revision}}</span><small>{{record.id}}</small></button>
        <p v-if="!documents.length" class="muted">No agreements have been recorded here yet.</p>
        <form class="upload-original" @submit.prevent="uploadOriginal"><h3>Already signed on paper?</h3><p>Upload a scanned original PDF. Uploading preserves the file; it does not verify signatures or mark an electronic agreement completed.</p><label>Document title<input v-model="uploadTitle" required maxlength="255" placeholder="Signed agreement — organization name" /></label><label>Original PDF · maximum 5 MB<input ref="uploadInput" type="file" accept="application/pdf" required @change="uploadFile=$event.target.files?.[0] || null" /></label><button :disabled="busy || !uploadFile">Upload original</button></form>
      </aside>
      <section v-if="!selected" class="agreement-editor"><h2>Your organization archive</h2><p>Choose an agreement or prepare a new draft. Existing signed documents remain preserved when you create a revised version.</p><p>No agreement has been issued or signed by opening this page.</p></section>
      <section v-else class="agreement-editor">
        <div class="document-heading"><div><p class="eyebrow">{{statusLabel(selected.data.status)}}</p><h2>{{selected.data.title}}</h2><p class="muted">Document {{selected.id}} · revision {{selected.revision}}</p></div><div class="document-downloads"><button v-if="selected.kind==='agreement'" :disabled="busy" @click="downloadPdf">Download PDF</button><button v-if="selected.kind==='agreement'" @click="downloadHtml">Download HTML copy</button><button v-else :disabled="busy" @click="downloadOriginal">Download original PDF</button></div></div>
        <template v-if="selected.kind==='agreement'">
          <form v-if="selected.data.status==='draft'" @submit.prevent="saveDraft">
            <p v-if="selected.data.templateSuggestion" class="agreement-callout"><strong>Starting point for this organization.</strong> {{selected.data.templateSuggestion.note}} Suggested names require verification; no retained draft is treated as approved or executed.</p>
            <p class="agreement-callout">This is an unexecuted draft. Reuse your reviewed contract text and complete its schedules. Saving or downloading a draft does not approve, issue or sign it.</p>
            <p v-if="missingDetails.length" class="agreement-callout">Complete before approval: {{missingDetails.join('; ')}}. You can save the draft while these details are being confirmed.</p><div class="party-grid"><fieldset v-for="side in ['practice','operator']" :key="side"><legend>{{side==='practice'?'Organization / business owner':'PlotTwistCo / service provider'}}</legend><label>Actual legal name<input v-model="draft.parties[side].legalName" maxlength="255" /></label><label>Legal address<textarea v-model="draft.parties[side].address" maxlength="1000" rows="2" /></label><label>{{isManagement?'Business notice contact':'Privacy / incident notice contact'}}<textarea v-model="draft.parties[side].noticeContact" maxlength="1000" rows="2" /></label><label v-if="!isManagement">HIPAA role<input v-model="draft.parties[side].hipaaRole" maxlength="200" placeholder="Covered entity / business associate / subcontractor" /></label></fieldset></div>
            <label>Effective date<input v-model="draft.effectiveDate" type="date" required /></label>
            <label>Agreement text<textarea v-model="draft.body" required maxlength="100000" rows="16" /></label><label>Completed terms and schedules<textarea v-model="draft.terms" required maxlength="50000" rows="8" placeholder="Approved service scope, notice contacts, reporting periods, rights requests, retention / export terms and schedules" /></label>
            <div class="party-grid"><fieldset><legend>Operator representative</legend><label>Designated signer<select v-model="draft.signers[0].accountId" required><option value="">Choose an operator</option><option v-for="s in signers.filter(s=>s.operator)" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>Signer title / authority<input v-model="draft.signers[0].capacity" required maxlength="120" /></label></fieldset><fieldset><legend>Organization representative</legend><label>Designated signer<select v-model="draft.signers[1].accountId" required><option value="">Choose an organization administrator</option><option v-for="s in signers.filter(s=>s.organization)" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>Signer title / authority<input v-model="draft.signers[1].capacity" required maxlength="120" /></label></fieldset></div>
            <p class="muted">Each representative must sign from their own active account and have authority for the entity shown. Two distinct accounts are required.</p><button :disabled="busy">Save draft</button><span v-if="dirty" class="muted"> Unsaved changes</span>
          </form>
          <article class="exact-document" aria-label="Exact saved agreement"><h3>{{selected.data.status==='draft'?'Review the exact saved document':'Agreement and signature evidence'}}</h3><p>Effective date: {{selected.data.effectiveDate || 'Not set'}}</p><div v-for="side in ['practice','operator']" :key="side" class="saved-party"><strong>{{selected.data.parties?.[side]?.legalName || 'Legal entity not completed'}}</strong><p>{{selected.data.parties?.[side]?.hipaaRole}}</p><p>{{selected.data.parties?.[side]?.address}}</p><p>{{selected.data.parties?.[side]?.noticeContact}}</p></div><pre>{{selected.data.body}}</pre><h4>Completed terms and schedules</h4><pre>{{selected.data.terms || 'Not completed'}}</pre><h4>Designated representatives</h4><p v-for="s in selected.data.signers || []" :key="s.accountId">{{signerName(s.accountId)}} · {{s.capacity}}</p><div v-for="s in selected.data.signatures || []" :key="s.accountId" class="signature-evidence"><strong>Signed: {{s.name}}</strong><p>{{s.capacity}} · {{s.signedAt}}</p><p>Account {{s.accountId}} · SHA-256 {{s.contentHash}}</p></div><p class="hash">SHA-256: {{selected.data.contentHash || selected.reviewHash}}</p></article>
          <div v-if="selected.data.status==='draft' && actor.operator" class="approval-panel"><label class="check-label"><input v-model="legalApproved" type="checkbox" :disabled="dirty" />I have reviewed this exact saved text, confirmed the legal parties and signers, and approve it for issuance.</label><button :disabled="busy || dirty || !legalApproved || missingDetails.length>0" @click="act('approve',{legalApproved:true,reviewHash:selected.reviewHash})">Approve exact version</button><button :disabled="busy || dirty || !selected.data.approvalHash" @click="act('issue')">Issue to designated signers</button></div>
          <form v-if="canSign" class="signing-panel" @submit.prevent="sign"><h3>Your signature</h3><p>Review the entire saved agreement above. Your signature applies only to this document hash and the legal capacity assigned to your account.</p><label>Your full signature name<input v-model="signatureName" required maxlength="200" autocomplete="name" /></label><label class="check-label"><input v-model="signatureConsent" type="checkbox" required />I am authorized to represent the stated party. I consent to electronic signatures and intend to sign this exact agreement.</label><button :disabled="busy || !signatureConsent">Sign this agreement</button></form>
          <p v-else-if="['issued','partially_signed'].includes(selected.data.status)" class="agreement-callout">This version is awaiting its designated representatives. Sign in with the assigned account to sign. You can copy this page's URL to that representative; no email is sent automatically.</p>
          <button v-if="selected.data.status==='completed'" :disabled="busy" @click="act('revise')">Prepare a new version</button>
        </template>
        <template v-else><p>Original filename: {{selected.data.name}}</p><p class="hash">Original SHA-256: {{selected.data.hash}}</p><p class="agreement-callout">{{selected.data.status==='verified_external'?'An operator reviewed this externally signed original. It remains distinct from agreements signed electronically in this workspace.':'This original is retained without changing its bytes. Its signatures and contracting parties have not yet been verified.'}}</p><dl v-if="selected.data.verifiedAt"><dt>Reviewed by</dt><dd>Account {{selected.data.verifiedBy}} · {{selected.data.verifiedAt}}</dd><dt>Review notes</dt><dd>{{selected.data.reviewNotes}}</dd></dl>
          <form v-if="actor.operator && selected.data.status==='uploaded_unverified'" @submit.prevent="verifyUpload"><h3>Review an externally signed original</h3><p>Download and inspect the actual PDF first. Record both signed parties, their authorized representatives and actual dates. This review does not create electronic signatures.</p><div class="party-grid"><fieldset v-for="side in ['practice','operator']" :key="side"><legend>{{side==='practice'?'Organization / business owner':'PlotTwistCo / service provider'}}</legend><label>Legal entity<input v-model="external.parties[side].legalName" required maxlength="255" /></label><label>Actual signer's name<input v-model="external.parties[side].signerName" required maxlength="200" /></label><label>Title / authority<input v-model="external.parties[side].capacity" required maxlength="200" /></label><label>Actual date signed<input v-model="external.parties[side].signedDate" type="date" required /></label></fieldset></div><label>Agreement effective date<input v-model="external.effectiveDate" type="date" required /></label><label>Verification notes<textarea v-model="external.reviewNotes" required maxlength="5000" rows="3" placeholder="How both signatures, authority, legal parties and the complete signed document were verified" /></label><button :disabled="busy || !originalOpened">Record external signature review</button><p v-if="!originalOpened" class="muted">Download the original PDF to begin your review.</p></form>
        </template>
        <details class="audit-history" @toggle="loadAudit"><summary>Document audit history</summary><ol><li v-for="(event,index) in events" :key="index">{{event.at}} · {{event.action}} · account {{event.actorUserId}}</li></ol><p v-if="!events.length">No audit entries loaded.</p></details>
      </section>
    </div>
  </main>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import api from '../../services/api';
const route=useRoute(),router=useRouter();
const organizations=ref([]),agencyId=ref(String(route.query.agencyId || '')),organization=ref({}),actor=ref(null),signers=ref([]),documents=ref([]),selected=ref(null),draft=ref(null),originalDraft=ref(''),busy=ref(false),error=ref(''),message=ref(''),legalApproved=ref(false),signatureName=ref(''),signatureConsent=ref(false),uploadTitle=ref(''),uploadFile=ref(null),uploadInput=ref(null),originalOpened=ref(false),events=ref([]);
const newType=ref('baa');
const isManagement=computed(()=>selected.value?.data.type==='management_agreement');
const missingDetails=computed(()=>{const result=[];for(const side of ['practice','operator'])for(const key of ['legalName','address','noticeContact',...(!isManagement.value?['hipaaRole']:[])])if(!draft.value?.parties?.[side]?.[key]?.trim())result.push(`${side==='practice'?'Organization':'PlotTwistCo'} ${({legalName:'legal name',address:'address',noticeContact:'notice contact',hipaaRole:'HIPAA role'})[key]}`);return result;});
const party=()=>({legalName:'',address:'',noticeContact:'',hipaaRole:''});
const external=ref({parties:{practice:{},operator:{}},effectiveDate:'',reviewNotes:''});
const headers={'X-Organization-Agreement':'1'};
const dirty=computed(()=>draft.value && JSON.stringify(draft.value)!==originalDraft.value);
const canSign=computed(()=>selected.value?.kind==='agreement' && ['issued','partially_signed'].includes(selected.value.data.status) && selected.value.data.signers?.some(s=>s.accountId===actor.value?.id) && !selected.value.data.signatures?.some(s=>s.accountId===actor.value?.id));
const base=()=>`/organization-agreements/${agencyId.value}`;
const statusLabel=status=>({draft:'Draft · not executed',issued:'Issued · awaiting signatures',partially_signed:'Partially signed',completed:'Executed electronically',uploaded_unverified:'Uploaded · unverified',verified_external:'Externally signed · reviewed'}[status] || status);
const signerName=id=>signers.value.find(s=>s.id===id)?.name || `Account ${id}`;
async function run(fn){busy.value=true;error.value='';message.value='';try{return await fn();}catch(e){error.value=e.response?.data?.error?.message || e.response?.data?.message || e.message;}finally{busy.value=false;}}
function choose(record){selected.value=record;legalApproved.value=false;signatureName.value='';signatureConsent.value=false;events.value=[];originalOpened.value=false;external.value={parties:{practice:{},operator:{}},effectiveDate:'',reviewNotes:''};if(record.kind==='agreement'){const d=record.data;draft.value={revision:record.revision,body:d.body,terms:d.terms || '',effectiveDate:d.effectiveDate || '',parties:{practice:{...party(),...d.parties?.practice},operator:{...party(),...d.parties?.operator}},signers:d.signers?.length===2?JSON.parse(JSON.stringify(d.signers)):[{accountId:'',capacity:''},{accountId:'',capacity:''}]};originalDraft.value=JSON.stringify(draft.value);}else draft.value=null;router.replace({query:{agencyId:agencyId.value,document:record.id}});}
async function refresh(selectedId=selected.value?.id){const {data}=await api.get(base());organization.value=data.organization;actor.value=data.actor;signers.value=data.signers;documents.value=data.documents;const found=data.documents.find(r=>r.id===selectedId);if(found)choose(found);else selected.value=null;}
async function loadArchive(){selected.value=null;actor.value=null;if(!agencyId.value)return;await run(()=>refresh(String(route.query.document || '')));}
async function createDraft(){await run(async()=>{const {data}=await api.post(`${base()}/agreements`,{type:newType.value}, {headers});await refresh(data.id);message.value='An unexecuted agreement draft was added to this organization.';});}
async function saveDraft(){await run(async()=>{const {data}=await api.put(`${base()}/agreements/${selected.value.id}`,draft.value,{headers});await refresh(data.id);message.value='Draft saved. The exact saved version is shown below for review.';});}
async function act(action,payload={}){await run(async()=>{const {data}=await api.post(`${base()}/agreements/${selected.value.id}/${action}`,payload,{headers});await refresh(data.id);message.value={approve:'Exact version approved. Issuance is a separate action.',issue:'Issued. Each designated representative must sign from their own account.',sign:'Your signature was retained with this exact document.',revise:'A new unexecuted version was created. The original remains preserved.'}[action];});}
async function sign(){await act('sign',{name:signatureName.value,consent:signatureConsent.value,contentHash:selected.value.data.contentHash});}
function saveBlob(blob,name){const url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=name;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function downloadPdf(){await run(async()=>{const {data}=await api.get(`${base()}/agreements/${selected.value.id}/pdf`,{responseType:'blob'});saveBlob(data,`agreement-${selected.value.id}.pdf`);});}
async function downloadHtml(){await run(async()=>{const {data}=await api.get(`${base()}/agreements/${selected.value.id}/html`,{responseType:'blob'});saveBlob(data,`agreement-${selected.value.id}.html`);});}
async function uploadOriginal(){await run(async()=>{const body=new FormData();body.append('title',uploadTitle.value);body.append('file',uploadFile.value);const {data}=await api.post(`${base()}/uploads`,body,{headers:{...headers,'Content-Type':'multipart/form-data'}});uploadFile.value=null;uploadTitle.value='';if(uploadInput.value)uploadInput.value.value='';await refresh(data.id);message.value='Original PDF retained. Its signatures remain unverified until operator review.';});}
async function downloadOriginal(){await run(async()=>{const {data}=await api.get(`${base()}/uploads/${selected.value.id}/original`,{responseType:'blob'});saveBlob(data,selected.value.data.name);originalOpened.value=true;});}
async function verifyUpload(){await run(async()=>{const {data}=await api.post(`${base()}/uploads/${selected.value.id}/verify`,{...external.value,sha256:selected.value.data.hash},{headers});await refresh(data.id);message.value='External signature review retained with the original PDF. No electronic signature was created.';});}
async function loadAudit(event){if(!event.target.open || !selected.value)return;await run(async()=>{events.value=(await api.get(`${base()}/documents/${selected.value.id}/audit`)).data;});}
onMounted(()=>run(async()=>{organizations.value=(await api.get('/organization-agreements/organizations')).data.organizations;if(!agencyId.value){const scoped=organizations.value.find(org=>org.slug===route.params?.organizationSlug);if(scoped)agencyId.value=String(scoped.id);}if(agencyId.value)await refresh(String(route.query.document || ''));}));
</script>
<style scoped>
.agreement-workspace{max-width:1500px;margin:auto;padding:32px;color:#18394e}.archive-heading,.document-heading{display:flex;justify-content:space-between;gap:24px;align-items:start}.archive-heading h1{font-size:32px;margin:0}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.1em;color:#547786;font-weight:700}.agreement-callout{background:#f0f6fc;border:1px solid #d2e2f1;padding:18px;border-radius:12px;line-height:1.6;margin:20px 0}.organization-picker{max-width:480px}.archive-layout{display:grid;grid-template-columns:300px minmax(0,1fr);gap:24px;margin-top:24px}.archive-list,.agreement-editor{padding:24px;background:white;border:1px solid #d8e4ed;border-radius:16px;min-width:0}.archive-list h2{font-size:22px}.archive-item{display:flex;flex-direction:column;text-align:left;width:100%;margin-top:12px;gap:8px;background:#fff!important;color:#18394e!important}.archive-item.selected{border-color:#2467a6;background:#edf5fc!important}.archive-item small,.hash{font-size:12px;overflow-wrap:anywhere}.archive-item span,.muted{font-size:14px;color:#60788b;line-height:1.6}.upload-original{border-top:1px solid #d8e4ed;margin-top:24px;padding-top:18px}.upload-original p{font-size:14px;line-height:1.6}.agreement-workspace label{display:flex;flex-direction:column;gap:7px;font-weight:600;font-size:14px;margin:16px 0}.agreement-workspace input,.agreement-workspace select,.agreement-workspace textarea{padding:10px;border:1px solid #bfd0df;border-radius:7px;font:inherit;min-width:0;max-width:100%}.agreement-workspace textarea{width:100%;box-sizing:border-box;line-height:1.6}.party-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.agreement-workspace fieldset{min-width:0;border:1px solid #d8e4ed;border-radius:10px;padding:16px}.agreement-workspace legend{font-weight:700;padding:0 7px}.agreement-workspace button{border:1px solid #2467a6;background:#2467a6;color:white;padding:10px 15px;border-radius:8px;font:inherit;cursor:pointer}.agreement-workspace button:disabled{opacity:.55;cursor:default}.document-downloads{display:flex;flex-wrap:wrap;gap:8px}.document-heading h2{font-size:24px;margin:7px 0}.exact-document{border:1px solid #d8e4ed;padding:24px;margin:28px 0;border-radius:12px}.exact-document pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;line-height:1.75}.saved-party p{white-space:pre-wrap;margin:5px 0}.saved-party{margin:18px 0}.signature-evidence{padding:15px;border-left:4px solid #17806c;background:#eff9f6;margin:12px 0;overflow-wrap:anywhere}.check-label{display:flex!important;flex-direction:row!important;align-items:flex-start;line-height:1.6}.check-label input{margin-top:5px}.approval-panel,.signing-panel{padding:20px;background:#f4f8fc;border-radius:12px;margin:20px 0}.approval-panel button+button{margin-left:8px}.audit-history{margin-top:30px;border-top:1px solid #d8e4ed;padding-top:20px}.audit-history li{margin:12px 0;font-size:13px}.agreement-error{padding:16px;background:#fff0f1;color:#92223b;border-radius:8px}.agreement-success{padding:16px;background:#ebf8f1;color:#1d6747;border-radius:8px}@media(max-width:950px){.archive-layout{grid-template-columns:1fr}.archive-list{max-height:480px;overflow:auto}.archive-heading,.document-heading{flex-direction:column}.party-grid{grid-template-columns:1fr}.agreement-workspace{padding:16px}.agreement-editor,.archive-list{padding:16px}}button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #caa24c;outline-offset:3px}
</style>
